const state={options:[],plan:null,hourly:[],selected:0,selectedSegment:0,sort:'balanced',zoom:1,map:null,routeLayer:null,heatLayer:null,liveLayer:null,mapRouteKey:null,heatBoundsKey:null,lastBounds:null,heat:false,live:false,liveBuses:[],liveRoute:null,liveTimer:null,etaTimer:null,lastTrafficAlerts:new Set(),alertTimer:null,hindi:false,nearbyStop:null,tipTime:null,stopListenersReady:false,compare:false,visibleOptions:[],heatKey:null,heatLoaded:false,networkMap:null,networkLayer:null,networkLines:[],networkData:null,networkConnections:[],intentConstraints:null};
const crowdText={en:{low:'Low crowd',medium:'Medium crowd',high:'High crowd'},hi:{low:'Kam bheed',medium:'Thodi bheed',high:'Bahut bheed'}};
