function hourLabel(value){const h=Number(value);return `${h%12||12}${h>=12?' PM':' AM'}`}
function todayLocal(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function updateDateSummary(){const d=$('date').value?new Date($('date').value+'T12:00:00'):new Date();const t=$('time').value||'08:30';const [h,m]=t.split(':').map(Number);$('dateSummary').textContent=`${d.toLocaleDateString(state.hindi?'hi-IN':'en-IN',{weekday:'short',day:'numeric',month:'short'})}, ${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`}
