function setGraphHour(h){h=Number(h);$('graphHourLabel').textContent=hourLabel(h);$('hourValue').textContent=`${h%12||12}:30 ${h>=12?'PM':'AM'}`;const x=8+(h-6)*244/14;$('graphMarker').setAttribute('d',`M${x} 7V91`);const profile=state.hourly.find(v=>v.hour===h);const y=profile?78-Number(profile.score)*.58:(h<=10?51-(h-6)*8:h>=16?22+(h-16)*9:30+Math.abs(13-h)*3);$('graphDot').setAttribute('cx',x);$('graphDot').setAttribute('cy',y)}
