 try{state.map=L.map(container,{zoomControl:false,scrollWheelZoom:true,touchZoom:true}).setView([28.6139,77.2090],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).addTo(state.map);state.routeLayer=L.layerGroup().addTo(state.map);state.heatLayer=L.featureGroup();state.liveLayer=L.layerGroup().addTo(state.map);state.map.on('tileerror',()=>{if(!$('mapCaption').textContent.includes('tiles unavailable'))$('mapCaption').textContent='Some map tiles unavailable · check connection'});setTimeout(()=>state.map&&state.map.invalidateSize(),50)}catch{container.innerHTML='<div class="map-notice">Street map could not be initialized.</div>'}
