 segments.forEach((points,index)=>{const leg=legs[index]||{},line=L.polyline(points,{color:routeColor,weight:6,opacity:.94,lineCap:'round',lineJoin:'round',className:'dkp-route-line'});line.bindPopup('<strong>Bus '+escapeHtml(leg.route_short_name||leg.route_id||'route')+'</strong><br>'+escapeHtml(leg.from_stop||'')+' → '+escapeHtml(leg.to_stop||'')+(known?'<br>Relative ticket activity '+score+'/100':'<br>Ticket profile unavailable')).addTo(state.routeLayer)});
