async function loadStopEtas(leg){const box=$('stopEtaInfo');if(!box)return;if(state.etaTimer){clearInterval(state.etaTimer);state.etaTimer=null}if(!leg?.from_stop_id){box.textContent='Live stop ETAs unavailable for this boarding point.';return}box.textContent='Checking live arrivals at '+(leg.from_stop||'your boarding stop')+'…';try{const response=await fetch(`/eta/stop/${encodeURIComponent(leg.from_stop_id)}`),data=await response.json();if(!data.available){box.textContent=data.note||'Live arrivals are unavailable.';return}const etas=data.etas||[];box.innerHTML=`<strong>Live arrivals · ${escapeHtml(leg.from_stop)}</strong>`+(etas.length?`<ul>${etas.slice(0,5).map(x=>`<li>Bus ${escapeHtml(x.bus_number||'—')} · ${escapeHtml(x.arrival_time||'time unavailable')}</li>`).join('')}</ul>`:'<p>No buses are currently listed for this stop.</p>')+`<small>Transport Stack estimate · stop-wide, not route-filtered</small>`;state.etaTimer=setInterval(()=>loadStopEtas(leg),15000)}catch{box.textContent='Could not reach the live ETA service.'}}
