async function initNetworkTwin(){
 const badge=$('twinNetworkBadge'),select=$('twinRoute');if(!badge||!select)return;badge.textContent='Loading GTFS network…';
 try{
  const response=await fetch('/network');if(!response.ok)throw Error('Network request failed');const data=await response.json();if(!data.available)throw Error(data.note||'Network unavailable');state.networkData=data;
  badge.textContent=`${Number(data.route_count).toLocaleString()} routes · ${Number(data.stop_count).toLocaleString()} stops`;
  const routes=data.routes||[];select.innerHTML=routes.map(r=>`<option value="${escapeHtml(r.route_id)}">${escapeHtml(r.short_name||r.route_id)}${r.long_name?' · '+escapeHtml(r.long_name):''}</option>`).join('');
  const mapNode=$('networkMap');if(!window.L||!mapNode)return;state.networkMap=L.map(mapNode,{zoomControl:false,scrollWheelZoom:true,touchZoom:true,preferCanvas:true}).setView([28.6139,77.2090],10);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).addTo(state.networkMap);state.networkLayer=L.featureGroup().addTo(state.networkMap);const renderer=L.canvas({padding:.4});const bounds=[];
  for(const route of routes)for(const shape of route.shapes||[]){if(shape.length<2)continue;const line=L.polyline(shape,{renderer,color:'#146b52',weight:1.2,opacity:.19});line.bindTooltip(`Route ${escapeHtml(route.short_name||route.route_id)}`,{sticky:true});line.on('click',()=>{select.value=route.route_id;state.networkConnections=[];styleNetworkTwin()});line.addTo(state.networkLayer);state.networkLines.push({routeId:route.route_id,line});bounds.push(...shape)}
  if(bounds.length)state.networkMap.fitBounds(L.latLngBounds(bounds),{padding:[18,18],maxZoom:11});state.networkMap.invalidateSize();
  select.addEventListener('change',()=>{state.networkConnections=[];styleNetworkTwin()});$('twinScenario').addEventListener('change',syncTwinFields);$('twinScenario').dispatchEvent(new Event('change'));$('twinSlowdown').addEventListener('input',()=> $('twinSlowdownLabel').textContent=$('twinSlowdown').value+'%');$('twinDemand').addEventListener('input',()=> $('twinDemandLabel').textContent=$('twinDemand').value+'%');$('twinExtraBuses').addEventListener('input',()=> $('twinExtraLabel').textContent=$('twinExtraBuses').value);$('twinPropagation').addEventListener('input',()=> $('twinPropagationLabel').textContent=$('twinPropagation').value+'%');$('runTwinScenario').addEventListener('click',runTwinScenario);styleNetworkTwin();
 }catch(e){console.error(e);badge.textContent='Network unavailable';$('twinScenarioResult').textContent='Could not load the static GTFS network. Try again after the planner has indexed its GTFS feed.'}
}
function syncTwinFields(){const scenario=$('twinScenario')?.value;document.querySelectorAll('.twin-field[data-scenario]').forEach(node=>node.hidden=node.dataset.scenario!==scenario)}
function styleNetworkTwin(){if(!state.networkLines.length)return;const selected=$('twinRoute')?.value,connected=new Set(state.networkConnections.map(x=>String(x.route_id)));for(const item of state.networkLines){if(item.routeId===selected)item.line.setStyle({color:'#bf5146',weight:3.4,opacity:.95});else if(connected.has(String(item.routeId)))item.line.setStyle({color:'#d2a331',weight:2.2,opacity:.82});else item.line.setStyle({color:'#146b52',weight:1.1,opacity:.15})}}
async function runTwinScenario(){const button=$('runTwinScenario'),box=$('twinScenarioResult'),scenario=$('twinScenario').value,routeId=$('twinRoute').value;if(!routeId){toast('Choose a route first');return}button.disabled=true;button.textContent='Simulating…';box.innerHTML='<p class="detail-summary">Calculating route and shared-stop impacts from GTFS…</p>';const params=new URLSearchParams({scenario,route_id:routeId,hour:String(Number(($('time').value||'08:30').slice(0,2))),time:$('time').value||'08:30',date:$('date').value||todayLocal(),day_type:state.plan?.day_type||'weekday',slowdown_pct:$('twinSlowdown').value,demand_increase_pct:$('twinDemand').value,dwell_min_per_10pct:$('twinDwell').value||'0.5',extra_buses:$('twinExtraBuses').value,connection_delay_pct:$('twinPropagation').value,from_stop:$('twinFrom')?.value||$('from').value,to_stop:$('twinTo')?.value||$('to').value});try{const response=await fetch('/network/simulate?'+params);const data=await response.json();if(!response.ok||!data.available)throw Error(data.note||'Scenario failed');state.networkConnections=data.connections||[];styleNetworkTwin();const delta=data.change_minutes,deltaLabel=delta==null?'not available':`${Number(delta)>0?'+':''}${Number(delta).toFixed(1)} min`;const before=data.baseline_minutes==null?'—':`${Number(data.baseline_minutes).toFixed(1)} min`,after=data.estimated_minutes==null?'No scheduled journey':`${Number(data.estimated_minutes).toFixed(1)} min`;const journey=data.journey_comparison;let journeyText='';if(journey){const describe=x=>x?`${x.routes.join(' → ')} · ${x.minutes} min · ${x.transfers} transfer${x.transfers===1?'':'s'}`:'No itinerary found';journeyText=`<p><b>Fastest schedule before:</b> ${escapeHtml(describe(journey.baseline))}<br><b>After removing route:</b> ${escapeHtml(describe(journey.after_disruption))}</p>${journey.baseline&&!journey.selected_route_used_by_baseline?'<p>The selected route was not in the fastest baseline, so this trip pair has no estimated time change.</p>':''}`}const connections=state.networkConnections.slice(0,12).map(x=>`<li>Route ${escapeHtml(x.short_name||x.route_id)} · ${Number(x.shared_stops)} shared stop${Number(x.shared_stops)===1?'':'s'}${Number(x.estimated_connection_delay_min)>0?` · stress-test transfer delay +${Number(x.estimated_connection_delay_min).toFixed(1)} min`:''}</li>`).join('');const assumptions=(data.assumptions||[]).map(x=>`<li>${escapeHtml(x)}</li>`).join('');box.innerHTML=`<div class="twin-metrics"><article><small>Baseline route time</small><strong>${before}</strong></article><article><small>Scenario time</small><strong>${after}</strong></article><article><small>Estimated change</small><strong>${deltaLabel}</strong></article><article><small>Connected routes</small><strong>${Number(data.connected_route_count)}</strong></article></div>${journeyText}<p><b>Relative ticket activity:</b> ${Number(data.crowd_score)}/100${scenario==='demand'?` → ${Number(data.estimated_crowd_score)}/100 under this demand assumption`:''} · ${Number(data.crowd_ticket_records).toLocaleString()} sampled tickets</p><details open><summary>Scenario assumptions</summary><ul>${assumptions}<li>${escapeHtml(data.connection_assumption||'')}</li></ul></details><details><summary>Routes sharing stops with ${escapeHtml(data.route_name)}</summary>${connections?`<ul>${connections}</ul>`:'<p>No shared-stop route connections found.</p>'}</details>`}catch(e){console.error(e);box.textContent=e.message||'Scenario simulation failed.'}finally{button.disabled=false;button.textContent='Run what-if scenario'}}
function showPlanner(){ $('plannerView').hidden=false;$('insightsView').hidden=true;$('accuracyView').hidden=true;$('taglineReveal').hidden=false;animateView($('plannerView'));$('pageHeading').innerHTML=state.hindi?'कम भीड़ वाला रास्ता चुनें<br>और सुकून से पहुँचें।':'A calmer ride starts<br>with a smarter route.'}
