async function loadHeatmap(){
 if(!state.map)return;
 if(!state.heat){state.heatLayer.clearLayers();if(state.map.hasLayer(state.heatLayer))state.map.removeLayer(state.heatLayer);state.heatKey=null;state.heatLoaded=false;state.heatBoundsKey=null;return}
 const hour=Number(($('time').value||'08:00').slice(0,2)),dayType=state.plan?.day_type||'weekday',key=dayType+':'+hour;if(state.heatKey===key&&state.heatLoaded)return;state.heatKey=key;state.heatLoaded=false;state.heatLayer.clearLayers();if(state.map.hasLayer(state.heatLayer))state.map.removeLayer(state.heatLayer);
 try{const response=await fetch('/crowd/heatmap?hour='+hour+'&day_type='+dayType),data=await response.json();if(!state.heat||state.heatKey!==key)return;state.heatLoaded=true;const routes=data.route_shapes||[],all=routes.flatMap(route=>route.geometry||[]);if(!all.length){$('mapCaption').textContent='No GTFS route shapes for this crowd sample';return}const color=score=>score>=68?'#bf5146':score<35?'#20835f':'#d2a331';for(const route of routes){const points=(route.geometry||[]).filter(point=>Array.isArray(point)&&Number.isFinite(Number(point[0]))&&Number.isFinite(Number(point[1])));if(points.length<2)continue;L.polyline(points,{color:color(Number(route.score)),weight:Number(route.score)>=68?6:4,opacity:.75,lineCap:'round',lineJoin:'round'}).bindPopup('<strong>Bus route '+escapeHtml(route.route)+'</strong><br>Relative ticket activity '+route.score+'/100<br>'+Number(route.ticket_records||0).toLocaleString()+' ticket records').addTo(state.heatLayer)}state.heatLayer.addTo(state.map);$('mapTitle').textContent='Ticket activity across bus routes';$('mapLegendText').textContent='Relative ticket activity by route';$('mapCaption').textContent='Ticket sample · '+dayType+' '+hour+':00 · not passenger counts';$('mapFooterText').textContent=routes.length+' GTFS route shapes · relative scores';$('mapArt').setAttribute('aria-label','Street map with representative bus routes coloured by relative ticket activity for '+dayType+' at '+hour+':00');if(state.heatBoundsKey!==key){const bounds=state.heatLayer.getBounds();if(bounds.isValid())state.map.fitBounds(bounds,{padding:[20,20],maxZoom:12});state.heatBoundsKey=key}}catch{$('mapCaption').textContent='Could not load the ticket activity layer'}
}
function setMapLayer(){state.heat=!state.heat;$('heatToggle').setAttribute('aria-pressed',String(state.heat));$('heatToggle').title=state.heat?'Hide crowd layer':'Show crowd layer';updateMap();toast(state.heat?'Relative crowd layer shown for this trip':'Route view restored')}
async function showLiveAlternative(heldRoute,holds){const box=$('liveRouteAlert');if(!box)return;if(!holds?.length){box.hidden=true;box.textContent='';return}const alternatives=state.options.map((option,index)=>({option,index,route:option.legs?.[0]?.route_short_name||option.legs?.[0]?.route_id||''})).filter(x=>x.route&&x.route.toLocaleLowerCase()!==String(heldRoute).toLocaleLowerCase());if(!alternatives.length){box.textContent=`Possible traffic hold on route ${heldRoute}. No alternate scheduled option was found for this trip.`;box.hidden=false;return}const unique=[...new Set(alternatives.map(x=>x.route))];const liveChecks=await Promise.all(unique.map(async route=>{try{const r=await fetch(`/live/route/${encodeURIComponent(route)}`);return r.ok?await r.json():null}catch{return null}}));const checks=new Map(unique.map((route,index)=>[route,liveChecks[index]]));const clear=alternatives.filter(x=>{const d=checks.get(x.route);return d?.available&&d.count>0&&!(d.traffic_holds||[]).length}).sort((a,b)=>a.option.travel_time_min-b.option.travel_time_min||a.option.transfers-b.option.transfers);const candidate=clear[0]||alternatives.slice().sort((a,b)=>a.option.travel_time_min-b.option.travel_time_min||a.option.transfers-b.option.transfers)[0],check=checks.get(candidate.route),verified=Boolean(clear.length);box.innerHTML=`<strong>Possible traffic hold on route ${escapeHtml(heldRoute)}.</strong> Bus ${escapeHtml(holds[0].vehicle_id||holds[0].label||'')} has remained nearly stationary for about ${Math.ceil((holds[0].held_seconds||90)/60)} min away from a mapped stop. This is not a confirmed schedule delay. <b>${verified?`Alternative: ${escapeHtml(candidate.option.name)} · ${candidate.option.travel_time_min} min scheduled. Live check found ${check.count} bus position${check.count===1?'':'s'} and no possible holds.`:`Fastest scheduled alternative: ${escapeHtml(candidate.option.name)} · ${candidate.option.travel_time_min} min. Its live status could not be confirmed.`}</b> <button type="button" class="text-button" id="viewLiveAlternative">View alternative →</button>`;box.hidden=false;$('viewLiveAlternative').addEventListener('click',()=>{setSelected(candidate.index);$('routeDetails').scrollIntoView({behavior:'smooth',block:'nearest'})})}
async function refreshLive(){if(!state.live)return;const route=state.options[state.selected]?.legs?.[0]?.route_short_name;if(!route){state.live=false;toast('Choose a scheduled bus route first.');return}try{const response=await fetch(`/live/route/${encodeURIComponent(route)}`),data=await response.json();if(!data.available){state.live=false;state.liveBuses=[];state.liveRoute=null;if(state.liveTimer){clearInterval(state.liveTimer);state.liveTimer=null}toast(data.note||'Live bus access is unavailable.');$('liveBusLabel').hidden=true;updateMap();return}state.liveRoute=route;state.liveBuses=data.buses||[];const holds=data.traffic_holds||[];$('liveBusLabel').textContent=state.liveBuses.length?`${state.liveBuses.length} fresh bus position${state.liveBuses.length===1?'':'s'} · ${holds.length} possible traffic hold${holds.length===1?'':'s'} · refreshes every 15 sec`:'Live feed connected · no fresh buses on this route';if(holds.length){const hold=holds[0],id=String(hold.vehicle_id||hold.label||route);if(!state.lastTrafficAlerts.has(id)){state.lastTrafficAlerts.add(id);toast(`Possible traffic hold on route ${route}. Checking scheduled alternatives.`)}$('liveBusLabel').title=`${data.traffic_notice||''} ${holds.map(x=>`${x.vehicle_id||x.label}: ${Math.ceil((x.held_seconds||90)/60)} min`).join(' · ')}`}else $('liveBusLabel').title=data.note||'Fresh vehicle positions';$('liveBusLabel').hidden=false;await showLiveAlternative(route,holds);updateMap()}catch{state.live=false;state.liveBuses=[];state.liveRoute=null;if(state.liveTimer){clearInterval(state.liveTimer);state.liveTimer=null}toast('Could not reach the live bus feed.');$('liveBusLabel').hidden=true;updateMap()}}
async function setLive(){if(state.live){state.live=false;state.liveBuses=[];state.liveRoute=null;if(state.liveTimer){clearInterval(state.liveTimer);state.liveTimer=null}$('liveBusLabel').hidden=true;$('liveRouteAlert').hidden=true}else{state.live=true;await refreshLive();if(state.live&&!state.liveTimer)state.liveTimer=setInterval(refreshLive,15000)}$('liveToggle').setAttribute('aria-pressed',String(state.live));$('liveToggle').title=state.live?'Hide live buses':'Show live buses';$('liveToggle').setAttribute('aria-label',state.live?'Hide live bus positions':'Show live bus positions');updateMap()}
function toggleSort(){state.sort=state.sort==='balanced'?'fast':state.sort==='fast'?'crowd':'balanced';$('sortBtn').textContent=state.sort==='fast'?'Fastest first⌄':state.sort==='crowd'?'Least crowded⌄':'Best balance⌄';renderOptions(state.options,true)}
function resetForm(){state.intentConstraints=null;state.heat=false;state.live=false;state.liveBuses=[];state.liveRoute=null;if(state.liveTimer){clearInterval(state.liveTimer);state.liveTimer=null}$('heatToggle').setAttribute('aria-pressed','false');$('liveToggle').setAttribute('aria-pressed','false');$('liveBusLabel').hidden=true;$('liveRouteAlert').hidden=true;$('from').value='Kashmere Gate';$('to').value='Connaught Place';$('date').value=todayLocal();$('time').value='08:30';$('comfort').value=50;$('travelProfile').value='standard';$('special').checked=false;updateComfort();updateDateSummary();updateMap();findJourneys() }
function setTimeFromSlider(){const h=Number($('hourRange').value);$('time').value=`${String(h).padStart(2,'0')}:30`;setGraphHour(h);updateDateSummary()}
function saveBlob(name,rows){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.map(r=>r.join(',')).join('\n')],{type:'text/csv'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
function wire(){
  $('findBtn').addEventListener('click',()=>{state.intentConstraints=null;findJourneys()});$('assistantPlan').addEventListener('click',planNaturalRequest);$('tripRequest').addEventListener('keydown',event=>{if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();planNaturalRequest()}});$('comfort').addEventListener('input',updateComfort);$('comfort').addEventListener('change',findJourneys);
  $('travelProfile').addEventListener('change',findJourneys);$('special').addEventListener('change',findJourneys);$('date').addEventListener('change',()=>{loadDataFeatures();findJourneys()});$('time').addEventListener('input',()=>{const h=Number($('time').value.slice(0,2))||8;$('hourRange').value=Math.max(6,Math.min(20,h));setGraphHour($('hourRange').value);updateDateSummary()});$('time').addEventListener('change',findJourneys);
  ['from','to'].forEach(id=>{$(id).addEventListener('input',updateMap);$(id).addEventListener('change',findJourneys)});
  $('swapBtn').addEventListener('click',()=>{const x=$('from').value;$('from').value=$('to').value;$('to').value=x;updateMap();findJourneys()});$('clearBtn').textContent='Reset';$('clearBtn').addEventListener('click',resetForm);
  $('sortBtn').addEventListener('click',toggleSort);$('compareBtn').addEventListener('click',toggleCompare);$('heatToggle').addEventListener('click',setMapLayer);$('liveToggle').addEventListener('click',setLive);

  $('hourRange').addEventListener('input',setTimeFromSlider);$('hourRange').addEventListener('change',findJourneys);$('applyTip').addEventListener('click',()=>{if(!state.tipTime)return;$('time').value=state.tipTime;$('hourRange').value=String(Number(state.tipTime.slice(0,2)));setGraphHour($('hourRange').value);findJourneys();toast(`Departure changed to ${state.tipTime}`)});
  $('nearbyStopBtn').addEventListener('click',()=>{if(!state.nearbyStop)return;$('from').value=state.nearbyStop.name;updateMap();findJourneys();toast(`Starting from ${state.nearbyStop.name}`)});
  document.querySelectorAll('.navlink').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.navlink').forEach(n=>n.classList.remove('active'));b.classList.add('active');b.dataset.view==='insights'?showInsights():b.dataset.view==='accuracy'?showAccuracy():showPlanner()}));$('backToPlan').addEventListener('click',()=>{showPlanner();document.querySelectorAll('.navlink').forEach(n=>n.classList.toggle('active',n.dataset.view==='planner'))});$('accuracyBackToPlan').addEventListener('click',()=>{showPlanner();document.querySelectorAll('.navlink').forEach(n=>n.classList.toggle('active',n.dataset.view==='planner'))});
  $('language').addEventListener('click',setLanguage);$('saveTrip').addEventListener('click',()=>{try{const journey={origin:$('from').value.trim(),destination:$('to').value.trim(),departure:$('time').value,day_type:state.plan?.day_type||'weekday'};if(!journey.origin||!journey.destination)throw Error('Add both stops first.');localStorage.setItem('delhi-ki-public:usual-journey',JSON.stringify(journey));renderSavedJourney(journey);updateSavedTripNotice();toast('Usual journey saved on this device')}catch(error){toast(error.message||'This browser could not save the journey.')}});$('alertToggle').addEventListener('click',toggleCrowdAlerts);syncCrowdAlertButton();
}
function setupTagline(){const box=$('taglineCopy'),words=box.textContent.trim().split(/\s+/);box.innerHTML=words.map((w,i)=>`<span class="tag-word" style="transition-delay:${Math.min(i*45,500)}ms">${escapeHtml(w)}</span>`).join(' ');const reveal=$('taglineReveal');if(!('IntersectionObserver'in window)){reveal.classList.add('visible');box.querySelectorAll('.tag-word').forEach(w=>w.classList.add('lit'));return}const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){reveal.classList.add('visible');box.querySelectorAll('.tag-word').forEach((w,i)=>setTimeout(()=>w.classList.add('lit'),i*55));observer.disconnect()}},{threshold:.35});observer.observe(reveal)}
async function loadDataFeatures(){try{const status=await(await fetch('/data/status')).json();try{const r=await(await fetch('/feature-readiness')).json(),a=r.accessibility||{};const lines=[`Live bus positions: ${r.live_vehicle_positions?.configured?'API key configured (map markers only)':'not configured'}`,`Live stop ETAs: ${r.bus_stop_etas?.configured?'ETA API connected':'on hold'}`,`Possible traffic holds: ${r.traffic_hold_detection?.configured?'live speed feed configured':'GTFS-RT key needed'}`,`Delay/disruption alerts: ${r.delay_alerts?.configured?'feed URLs set; integration pending':'TripUpdates and ServiceAlerts feeds missing'}`,`Wheelchair journeys: ${a.available?'GTFS flags available':'not verified; unknown routes remain labeled unverified'}`,`Public OSM stop matches: ${a.osm_stop_data?.matched_gtfs_stops||0} GTFS stops within ${a.osm_stop_data?.matching_radius_m||50} m; partial evidence only`,`Walking distance: ${r.pedestrian_routing?.configured?'routing key configured':'pedestrian routing provider missing'}`,`Women’s safety ranking: unavailable; verified safety dataset missing`];$('featureReadinessBody').textContent=lines.join(' · ')}catch{}$('dataSourceNote').textContent=status.available?`${Number(status.records).toLocaleString()} October ticket records · ${status.gtfs?.routes?.toLocaleString()||'No'} GTFS routes · ${status.gtfs?.stops?.toLocaleString()||'No'} stops · historical GPS speeds: ${status.gps_history?.files_processed||0}/31 days. Crowd is relative, not passenger counts.`:'No ticket data loaded; synthetic estimates only.';const stops=await(await fetch('/stops')).json();$('stopSuggestions').innerHTML=(stops.stops||[]).map(s=>`<option value="${escapeHtml(s)}"></option>`).join('');if(!state.stopListenersReady){['from','to'].forEach(id=>$(id).addEventListener('input',async()=>{const q=$(id).value.trim();if(q.length<2)return;try{const res=await(await fetch(`/stops?q=${encodeURIComponent(q)}`)).json();$('stopSuggestions').innerHTML=(res.stops||[]).map(x=>`<option value="${escapeHtml(x)}"></option>`).join('')}catch{}}));state.stopListenersReady=true}const day=($('date').value?new Date($('date').value+'T12:00:00'):new Date()).getDay();const trend=await(await fetch(`/crowd/trends?day_type=${day===0||day===6?'weekend':'weekday'}`)).json();if(trend.hours?.length){const hs=trend.hours.filter(v=>v.hour>=6&&v.hour<=20).sort((a,b)=>a.hour-b.hour);state.hourly=hs;const pts=hs.map(v=>({x:8+(v.hour-6)*244/14,y:78-v.score*.58}));const path=pts.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(' ');$('timeGraph').querySelector('path').setAttribute('d',path);$('timeGraph').querySelectorAll('path')[1].setAttribute('d',`${path} L252 90 L8 90 Z`);$('timeGraph').setAttribute('aria-label','Ticket-derived relative activity by hour for the selected day type');setGraphHour(Number(($('time').value||'08:00').slice(0,2)))}}catch{}}
function renderSavedJourney(journey){if(!journey)return;$('savedTripText').textContent=`Saved on this device: ${journey.origin} → ${journey.destination} at ${journey.departure}.`;$('saveTrip').textContent='Update saved journey →'}
function updateSavedTripNotice(){try{const saved=JSON.parse(localStorage.getItem('delhi-ki-public:usual-journey')||'null');if(!saved)return;renderSavedJourney(saved);const same=saved.origin.trim().toLocaleLowerCase()===($('from').value||'').trim().toLocaleLowerCase()&&saved.destination.trim().toLocaleLowerCase()===($('to').value||'').trim().toLocaleLowerCase();const option=state.options[0];if(!same||!option?.crowd_data_backed||Number(option.crowd_score)<68)return;const tip=state.plan?.leave_tip?.time;$('savedTripText').textContent=`Heads-up for your saved trip: ${option.legs?.[0]?.route_short_name||'This route'} has high sampled ticket activity (${option.crowd_score}/100) around ${saved.departure}. ${tip?`The city-wide sample is quieter around ${tip}.`:''} Historical sample only, not a live alert.`}catch{}}
function syncCrowdAlertButton(){const button=$('alertToggle');if(!button)return;const enabled=localStorage.getItem('delhi-ki-public:crowd-alerts')==='on';button.setAttribute('aria-pressed',String(enabled));button.textContent=enabled?'Turn off crowd alerts':'Enable crowd alerts →';if(enabled&&'Notification'in window&&Notification.permission==='granted'&&!state.alertTimer){checkCrowdAlert();state.alertTimer=setInterval(checkCrowdAlert,30*60*1000)}else if((!enabled||!('Notification'in window)||Notification.permission!=='granted')&&state.alertTimer){clearInterval(state.alertTimer);state.alertTimer=null}}
function toggleCrowdAlerts(){if(localStorage.getItem('delhi-ki-public:crowd-alerts')==='on'){localStorage.removeItem('delhi-ki-public:crowd-alerts');if(state.alertTimer){clearInterval(state.alertTimer);state.alertTimer=null}syncCrowdAlertButton();toast('Crowd alerts turned off on this device');return}let saved;try{saved=JSON.parse(localStorage.getItem('delhi-ki-public:usual-journey')||'null')}catch{}if(!saved?.origin||!saved?.destination){toast('Save your usual journey first');return}if(!('Notification'in window)){toast('Browser notifications are not supported here');return}const activate=()=>{localStorage.setItem('delhi-ki-public:crowd-alerts','on');syncCrowdAlertButton();toast('Historical crowd alerts enabled while this planner is open')};if(Notification.permission==='granted'){activate();return}if(Notification.permission==='denied'){toast('Notifications are blocked in this browser settings');return}Notification.requestPermission().then(permission=>{if(permission==='granted')activate();else toast('Notification permission was not granted')})}
async function checkCrowdAlert(){if(localStorage.getItem('delhi-ki-public:crowd-alerts')!=='on')return;try{const saved=JSON.parse(localStorage.getItem('delhi-ki-public:usual-journey')||'null');if(!saved?.origin||!saved?.destination)return;const date=todayLocal(),params=new URLSearchParams({from:saved.origin,to:saved.destination,time:saved.departure||'08:30',date}),response=await fetch('/plan?'+params);if(!response.ok)return;const plan=await response.json(),route=plan.options?.find(option=>option.crowd_data_backed&&Number(option.crowd_score)>=68);if(!route)return;const routeId=route.legs?.[0]?.route_short_name||route.legs?.[0]?.route_id||route.name,key=`delhi-ki-public:last-alert:${date}:${routeId}`;if(localStorage.getItem(key))return;localStorage.setItem(key,'sent');new Notification('High historical ticket activity',{body:`Your saved trip ${saved.origin} → ${saved.destination} is typically busy around ${saved.departure}. This is an October ticket pattern, not live occupancy.`})}catch{}}
function loadSavedJourney(){try{const saved=JSON.parse(localStorage.getItem('delhi-ki-public:usual-journey')||'null');if(saved?.origin&&saved?.destination){$('from').value=saved.origin;$('to').value=saved.destination;$('time').value=saved.departure||'08:30';const h=Number($('time').value.slice(0,2))||8;$('hourRange').value=Math.max(6,Math.min(20,h));setGraphHour($('hourRange').value);updateDateSummary();renderSavedJourney(saved)}}catch{}}
function init(){const now=new Date();$('date').value=now.toISOString().slice(0,10);const h=Number(($('time').value||'08:30').slice(0,2));$('hourRange').value=Math.max(6,Math.min(20,h));setGraphHour($('hourRange').value);updateDateSummary();updateComfort();setupTagline();wire();loadSavedJourney();updateMap();loadDataFeatures();findJourneys()}
initStreetMap();init();
